    // Exact-old-hash CAS under the existing exclusive admin channel lock; rename is within the private filesystem.
    $report['runtime_switch_started']=true;if(!rename($staged,$runtimePath))hotelFail('runtime_switch_unconfirmed');
    hotelRuntime($app,$runtimeSha,HOTEL_CAMPAIGN,$bootstrapPin);$report['runtime_file_installed']=true;$report['runtime_sha256']=$runtimeSha;
    hotelWriteNew($work.'/runtime-switch.readback.json',HotelServerInputs::json(['runtime_sha256'=>$runtimeSha,'campaign_id'=>HOTEL_CAMPAIGN,'bootstrap_sha256'=>$bootstrapPin,'enabled_campaigns'=>0]));
    $authorizedNew=static function()use($app,$work,$intentSha,$runtimeSha,$bootstrapPin):bool{
        hotelInstalled($app);hotelRead($work.'/intent.json',65536,null,$intentSha);hotelRuntime($app,$runtimeSha,HOTEL_CAMPAIGN,$bootstrapPin);return true;
    };
    $report['phase']='enable';hotelEnabled($pdo,null);
    hotelWriteNew($work.'/enable.intent.json',HotelServerInputs::json(['operation_id'=>HOTEL_OPERATION,'campaign_id'=>HOTEL_CAMPAIGN,'bootstrap_sha256'=>$bootstrapPin,'runtime_sha256'=>$runtimeSha,'state'=>'single_enable_starting']));
    $report['enable_invoked']=true;$enabled=$cycle->enable(HOTEL_CAMPAIGN,$bootstrapPin,$authorizedNew);
    if(($enabled['enabled']??null)!==true||($enabled['state']??null)!=='ready'||($enabled['new_accepted']??null)!==0
        ||($enabled['stage_index']??null)!==0||($enabled['bootstrap_sha256']??null)!==$bootstrapPin)hotelFail('enable_readback_unconfirmed');
    hotelWriteNew($work.'/enable.readback.json',HotelServerInputs::json($enabled));
    hotelInstalled($app);hotelRuntime($app,$runtimeSha,HOTEL_CAMPAIGN,$bootstrapPin);hotelEnabled($pdo,HOTEL_CAMPAIGN);
    $report['enabled_snapshot']=$enabled;$report['activated_at_utc']=gmdate('c');$report['continuation']='existing_cron_only';
    $report['central41']='UNKNOWN';$report['phase']='complete';$report['state']='handoff_enabled';
}catch(Throwable $e){
    $message=$e->getMessage();$report['reason']=preg_match('/\A[a-z][a-zA-Z0-9_]{1,100}\z/D',$message)?$message:'handoff_unconfirmed';
    $report['required_next_step']='read_back_this_original_operation_no_replay';
}finally{
    if($pdo instanceof PDO&&$pdo->inTransaction())try{$pdo->rollBack();}catch(Throwable $ignored){}
    while(ob_get_level()>$level)ob_end_clean();
    try{
        if($target){$envelope=hotelSeal($report);if($ownedWork&&$work!==null)hotelWriteNew($work.'/result.sealed.json',json_encode($envelope,JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));}
    }catch(Throwable $ignored){$envelope=['operation'=>HOTEL_ACTIVATION_KIND,'state'=>'HOLD','reason'=>'sealed_handoff_result_unconfirmed','operator_provider_calls'=>0];}
    if(is_resource($lock)){flock($lock,LOCK_UN);fclose($lock);}umask($mask);
}
echo json_encode($envelope,JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR),"\n";
exit($report['state']==='handoff_enabled'&&$envelope['state']==='sealed'?0:1);
